-/****************************************************************************/
-int ExtractOneStructure( STRUCT_DATA *sd,
-                         INPUT_PARMS *ip,
-                         char *szTitle,
-                         inchi_InputEx *inp,
-                         INCHI_IOSTREAM *log_file,
-                         INCHI_IOSTREAM *out_file,
