-    szCoord = NULL;
-
-    /* chiral flag */
-
-    /* *****************************************************************************
-     * Chiral flags are set in:
-     * - ReadTheStructure() inchi-1, wInChI
-     * - e_IchiMain.c -- main()               -- C example of calling InChI dll
-     * - inchi_dll.c  ExtractOneStructure -- InChI dll code (here)
