-
-    if (( ip->nMode & REQ_MODE_CHIR_FLG_STEREO ) && ( ip->nMode & REQ_MODE_STEREO ))
-    {
-        if (ip->bChiralFlag & FLAG_SET_INP_AT_CHIRAL)
-        {
-            /* absolute stereo */
