-    *num_inp += 1;
-
-err_exit:
-
-    if (at)
-    {   /* if not moved to orig_inp_data/then nullified */
-        inchi_free( at );
-    }
-    if (szCoord)
-    {
-        inchi_free( szCoord );
-    }
-
-    nRet = TreatErrorsInReadTheStructure( sd, ip, LOG_MASK_NO_WARN, NULL,
-                                          log_file, out_file, prb_file,
-                                          orig_inp_data, num_inp );
-
-    return nRet;
