-    }
-    else
-    {
-        argc = 1;
-        argv[0] = "";
-        argv[1] = NULL;
-    }
-
-    if ((argc == 1
-#ifdef TARGET_API_LIB
-        && ( !inpInChI || !inpInChI->szInChI ))
-#endif
-
-        || (argc == 2 && ( argv[1][0] == INCHI_OPTION_PREFX ) &&
-        ( !strcmp( argv[1] + 1, "?" ) || !inchi_stricmp( argv[1] + 1, "help" ) ))) /* djb-rwth: addressing LLVM warnings */
-    {
