+{
+    if (!out)
+    {
+        return;
+    }
+
+    if (out->szInChI)
+    {
+        inchi_free( out->szInChI );
+    }
+    if (out->szLog)
+    {
+        inchi_free( out->szLog );
+    }
+    if (out->szMessage)
+    {
+        inchi_free( out->szMessage );
+    }
+
+    memset( out, 0, sizeof( *out ) ); /* djb-rwth: memset_s C11/Annex K variant? */
+}
