+	MCOperand_CreateImm0(Inst, (SignExtend64((Imm << 2), 20)));
+	return MCDisassembler_Success;
+}
+
+static DecodeStatus decodeJumpOperand(MCInst *Inst, uint64_t Imm,
+				      int64_t Address, const void *Decoder)
+{
