+  case 6: \
+    tmp = fieldname(insn, 12, 4); \
+    if (!Check(&S, DecodeARRegisterClass(MI, tmp, Address, Decoder))) { return MCDisassembler_Fail; } \
+    tmp = fieldname(insn, 4, 4); \
