 		  char dNSName[256];
+		  u_int16_t dNSName_len;

 		  i += 2;

@@ -532,25 +533,26 @@ static void processCertificateElements(struct ndpi_detection_module_struct *ndpi
 			       packet->payload[i+1] & 0xFF,
 			       packet->payload[i+2] & 0xFF,
