                         first, last);
diff --git a/src/tiffio.c b/src/tiffio.c
index cd59a83..5a761ff 100644
--- a/src/tiffio.c
+++ b/src/tiffio.c
@@ -2347,7 +2347,8 @@ size_t        amount;
     amount = L_MIN((size_t)length, mstream->hw - mstream->offset);

