-	out.s = space;
+	out.s = space > 0 ? space - 1 : 0;
 	out.n = 0;

 	/* Note: using a NULL context is safe here */
 	fz_format_string(NULL, &out, snprintf_emit, fmt, args);
-	snprintf_emit(NULL, &out, 0);
