-            child = 0;
+            rc_decrement(child, "gx_device_unsubclass(device)");
         }
     }
-    if(child)
-        child->parent = dev;
     dev->parent = parent;

     /* If this device has a dynamic stype, we wnt to keep using it, but we copied
