 parser.c | 86 ++++++++++++++++++++++++++++++++++++++++++--------------
 tree.c   |  9 ++++--
 2 files changed, 71 insertions(+), 24 deletions(-)

diff --git a/parser.c b/parser.c
index 7de41a2..40972af 100644
--- a/parser.c
+++ b/parser.c
@@ -7267,6 +7267,39 @@ xmlParseReference(xmlParserCtxtPtr ctxt) {
