+        char *lname = NULL;
         if (tfdev->sep_file[comp_num] != NULL) {
             tiff_filename_from_tiff(tfdev->tiff[comp_num], &name);
-            code = gx_device_close_output_file(pdev, name, tfdev->sep_file[comp_num]);
